// frontend/src/nodes/BaseNode.jsx
import React from 'react';
import { Handle, Position } from 'reactflow'; // Import Position if needed

// Color mapping for each node type
const NODE_COLORS = {
  customInput: { header: '#0ea5e9', bg: '#f0f9ff' },
  llm: { header: '#8b5cf6', bg: '#f3e8ff' },
  customOutput: { header: '#ec4899', bg: '#fdf2f8' },
  text: { header: '#10b981', bg: '#f0fdf4' },
  math: { header: '#f59e0b', bg: '#fffbeb' },
  api: { header: '#3b82f6', bg: '#dbeafe' },
  condition: { header: '#ef4444', bg: '#fef2f2' },
  csv: { header: '#059669', bg: '#f0fdf4' },
  custom: { header: '#6b7280', bg: '#f3f4f6' },
};

const BaseNode = ({ data, type }) => {
  const { label, handles = [], content } = data; // Destructure handles from data
  const colors = NODE_COLORS[type] || NODE_COLORS.custom;

  return (
    <div
      style={{
        width: '220px',
        borderRadius: '8px',
        border: `1px solid ${colors.header}`,
        backgroundColor: colors.bg,
        boxShadow: '0 2px 8px rgba(0,0,0,0.05)',
        fontFamily: "'Inter', sans-serif",
        position: 'relative', // Needed if handles are absolutely positioned within
      }}
    >
      <div
        style={{
          padding: '8px 12px',
          backgroundColor: colors.header,
          color: 'white',
          fontSize: '13px',
          fontWeight: 600,
          borderBottom: `1px solid ${colors.header}`,
        }}
      >
        {label || type}
      </div>
      <div style={{ padding: '10px 12px', fontSize: '13px', color: '#374151' }}>
        {content}
      </div>
      {/* Iterate through the handles array passed from the specific node component */}
      {handles.map((handle) => {
        // Determine the reactflow Position based on the handle's position string
        let positionEnum;
        switch (handle.position) {
          case 'left':
            positionEnum = Position.Left;
            break;
          case 'right':
            positionEnum = Position.Right;
            break;
          case 'top':
            positionEnum = Position.Top;
            break;
          case 'bottom':
            positionEnum = Position.Bottom;
            break;
          default:
            // Default to Left or Right if not specified, or handle as needed
            positionEnum = Position.Left; // Or maybe log a warning
        }

        return (
          <Handle
            key={handle.id} // Use handle ID as key for uniqueness
            type={handle.type} // 'target' or 'source'
            position={positionEnum} // Use the converted Position enum
            id={handle.id} // The specific ID for the handle
            style={{
              // Apply styling, potentially using the color from NODE_COLORS
              // or handle-specific styles if passed in the handle object
              background: handle.style?.background || colors.header,
              border: handle.style?.border || '2px solid white',
              // If you need to handle vertical distribution for multiple left/right handles,
              // you might need to calculate the 'top' style here based on index
              // within the filtered handles array for that position.
              // For now, reactflow handles default positioning.
            }}
          />
        );
      })}
    </div>
  );
};

export default BaseNode;
